{"content": "#!/usr/bin/env python3
"""
Rebuild and compress Book 6: Moon Rock.
The original file was corrupted. This script:
1. Restores proper HTML structure
2. Keeps all remaining Elena Marchetti content
3. Writes clean, valid HTML
"""
import re as regex

path = '/home/bob/books/Moon_Base_Series/Book_1_Moon_Rock/Book_6_Moon Rock.html'

with open(path, 'r', encoding='utf-8') as f:
    content = f.read()

# Step 1: Fix all broken HTML

# Fix <h1> that contains </h1> as separate line 
content = regex.sub(r'<h1 class="chapter-title" id="ch(\d+)">\n</h1>\n',
                   r'<h1 class="chapter-title" id="ch\1"></h1>\n', content)

# Read all the content between body tags
body_match = regex.search(r'<body>(.*?)</body>', content, regex.DOTALL)
if body_match:
    body = body_match.group(1)
else:
    body = content

# Find all chapter starts
chapters = regex.split(r'(<h2>Chapter \d+</h2>\s*\n\s*<h1 class="chapter-title"[^>]*>Chapter \d+[^<]*</h1>)', body)

# Process each part
output_parts = []
for part in chapters:
    if not part.strip():
        continue
    if part.startswith('<h2>Chapter'):
        # This is a chapter header - keep it
        output_parts.append(part)
    else:
        # This is body content between chapters
        # Remove duplicate scene-breaks
        part = regex.sub(r'(<p class="scene-break">\* \* \*</p>\s*){3,}', 
                         r'<p class="scene-break">* * *</p>\n', part)
        # Remove empty paragraphs 
        part = regex.sub(r'<p>\s*</p>', '', part)
        # Remove orphan content
        part = regex.sub(r'<p[^>]*>The news was met with a mixture of relief[^<]*</p>\s*', '', part)
        part = regex.sub(r'<p[^>]*>The idea was met with skepticism at first[^<]*</p>\s*', '', part)
        part = regex.sub(r'<p[^>]*>"Keep going," came the reply\.[^<]*</p>\s*', '', part)
        part = regex.sub(r'<p[^>]*>The others nodded, their faces set with determination[^<]*</p>\s*', '', part)
        output_parts.append(part)

new_body = '\n'.join(output_parts)

# Fix the missing chapter headers
# The chapters we know exist in the content are 1, 2, 3, 8, 17, 18, 19, 20
# We need to ensure all chapter headers from TOC are present

toc_chapters = [
    ('1', 'The Landing Gone Wrong'),
    ('2', 'Emergency Protocols'),
    ('3', 'The First Night'),
    ('4', 'Oxygen Budget'),
    ('5', 'The Hidden Crevasse'),
    ('6', 'Water Ice Gamble'),
    ('7', 'Communication Blackout'),
    ('8', 'The Descent'),
    ('9', 'Cave Systems'),
    ('10', 'Discovery in the Dark'),
    ('11', 'The Storm Above'),
    ('12', 'Resource War'),
    ('13', 'The Fallback Plan'),
    ('14', 'Improvisation'),
    ('15', 'The Rescue Attempt'),
    ('16', 'Countdown'),
    ('17', 'Last Resort'),
    ('18', 'The Signal'),
    ('19', 'Extraction'),
    ('20', 'Epilogue: The New Normal'),
]

# Check which chapters exist in the body
for num, title in toc_chapters:
    pattern = f'Chapter {num} — {title}'
    if pattern in new_body:
        pass  # Chapter exists
    else:
        # Chapter is missing - add a placeholder
        ch_header = f'<h2>Chapter {num:02d}</h2>\n\n<h1 class="chapter-title" id="ch{num}">Chapter {num} — {title}</h1>\n\n'
        # Find where to insert it (after the previous chapter)
        prev_num = str(int(num) - 1)
        prev_title = toc_chapters[int(num)-2][1] if int(num) > 1 else None

        if prev_title and f'Chapter {prev_num} — {prev_title}' in new_body:
            # Find the end of the previous chapter (look for next chapter marker or end)
            prev_pattern = f'Chapter {prev_num} — {prev_title}'
            prev_end = new_body.find(prev_pattern) + len(prev_pattern)
            # Find the next chapter header or end of body
            next_marker = f'<h2>Chapter {int(num):02d}'
            after_prev = new_body[prev_end:]
            # Insert right before next chapter marker
            if next_marker in after_prev:
                insert_pos = new_body.find(next_marker, prev_end)
            else:
                insert_pos = len(new_body)

            new_body = new_body[:insert_pos] + ch_header + new_body[insert_pos:]

# Reassemble full HTML
full_html = f'''<!DOCTYPE html>
