# This is getting too complex. Let me just reconstruct from what we have.
# Extract the front matter (everything before Chapter 1)
front_matter_end = content.find('Chapter 1 — The Landing Gone Wrong')
if front_matter_end > 0:
    front_matter = content[:front_matter_end]
    # Find the start of the TOC area
    toc_start = front_matter.rfind('<div class="toc-page">', 0, front_matter_end)
    if toc_start > 0:
        front_matter = content[:toc_start]

# Extract back matter  
back_matter_start = content.rfind('<div class="back-matter">')
if back_matter_start > 0:
    back_matter = content[back_matter_start:]
else:
    back_matter = ''

